import{_ as e,o as d,c as o,ag as a}from"./chunks/framework.B7PviQjB.js";const b=JSON.parse('{"title":"Configuration","description":"Every backend environment variable and frontend build-time variable a Wafflebase deployment reads.","frontmatter":{"title":"Configuration","description":"Every backend environment variable and frontend build-time variable a Wafflebase deployment reads.","type":"reference"},"headers":[],"relativePath":"developers/self-hosting/configuration.md","filePath":"developers/self-hosting/configuration.md"}'),r={name:"developers/self-hosting/configuration.md"};function n(c,t,i,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Every environment variable a Wafflebase deployment reads, grouped by feature.</p><p><strong>Conventions.</strong> Backend variables go in <code>packages/backend/.env</code> or the container environment and are read when the process starts. Frontend <code>VITE_*</code> variables are compiled into the bundle when you build it; setting them on the server that serves the files does nothing. The backend does not validate its configuration as a whole at boot. Only <code>JWT_SECRET</code> stops startup when missing; most other values fail when the feature that reads them first runs.</p><h2 id="backend-required" tabindex="-1">Backend: required <a class="header-anchor" href="#backend-required" aria-label="Permalink to &quot;Backend: required&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>Yes</td><td>none</td><td>PostgreSQL connection string</td></tr><tr><td><code>JWT_SECRET</code></td><td>Yes</td><td>none</td><td>Signs access tokens and Yorkie auth tokens, and refresh tokens unless <code>JWT_REFRESH_SECRET</code> is set. Missing, the backend exits with <code>JWT_SECRET is required</code></td></tr><tr><td><code>GITHUB_CLIENT_ID</code></td><td>Yes</td><td>none</td><td>GitHub OAuth app client ID</td></tr><tr><td><code>GITHUB_CLIENT_SECRET</code></td><td>Yes</td><td>none</td><td>GitHub OAuth app client secret</td></tr><tr><td><code>GITHUB_CALLBACK_URL</code></td><td>Yes</td><td>none</td><td><code>https://&lt;backend&gt;/auth/github/callback</code>. Its scheme also decides whether cookies are <code>Secure</code>; see <a href="/docs/developers/self-hosting/sign-in.html#serve-sign-in-over-https">Serve sign-in over HTTPS</a></td></tr><tr><td><code>FRONTEND_URL</code></td><td>Yes</td><td>none</td><td>Frontend public origin. The CORS origin and the post-login redirect target</td></tr></tbody></table><h2 id="backend-server-and-runtime" tabindex="-1">Backend: server and runtime <a class="header-anchor" href="#backend-server-and-runtime" aria-label="Permalink to &quot;Backend: server and runtime&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>PORT</code></td><td>No</td><td><code>3000</code></td><td>HTTP port</td></tr><tr><td><code>NODE_ENV</code></td><td>No</td><td>unset; <code>production</code> in the image</td><td><code>production</code> removes the MinIO storage defaults and is the last fallback for <code>Secure</code> cookies</td></tr><tr><td><code>LOG_LEVEL</code></td><td>No</td><td><code>info</code></td><td>Pino log level</td></tr><tr><td><code>BACKEND_TRUST_PROXY</code></td><td>No</td><td><code>0</code></td><td>Number of proxy hops to trust for the client IP. Set <code>1</code> behind one TLS proxy</td></tr><tr><td><code>BACKEND_JSON_BODY_LIMIT</code></td><td>No</td><td><code>25mb</code></td><td>Request body limit for JSON, form, and text bodies. Raise it if large imports with inline images are rejected</td></tr><tr><td><code>WAFFLEBASE_API_ORIGIN</code></td><td>No</td><td>origin of <code>GITHUB_CALLBACK_URL</code></td><td>The backend&#39;s public origin. Used to recognize this deployment&#39;s own absolute image URLs when copying a document across workspaces. Set it to the same origin as <code>VITE_BACKEND_API_URL</code></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Set <code>BACKEND_TRUST_PROXY</code> only when a proxy really is in front. At <code>0</code> behind a proxy, every request shares one rate-limit bucket. Above <code>0</code> with no proxy, clients can spoof <code>X-Forwarded-For</code> and evade rate limits.</p></div><h2 id="backend-sessions-and-cookies" tabindex="-1">Backend: sessions and cookies <a class="header-anchor" href="#backend-sessions-and-cookies" aria-label="Permalink to &quot;Backend: sessions and cookies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>JWT_REFRESH_SECRET</code></td><td>No</td><td><code>JWT_SECRET</code></td><td>Signs refresh tokens. Set an independent value</td></tr><tr><td><code>JWT_ACCESS_EXPIRES_IN</code></td><td>No</td><td><code>1h</code></td><td>Access token lifetime</td></tr><tr><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td>No</td><td><code>7d</code></td><td>Refresh token lifetime</td></tr><tr><td><code>JWT_ACCESS_COOKIE_MAX_AGE_MS</code></td><td>No</td><td><code>3600000</code></td><td>Access cookie lifetime. Keep it consistent with the token lifetime</td></tr><tr><td><code>JWT_REFRESH_COOKIE_MAX_AGE_MS</code></td><td>No</td><td><code>604800000</code></td><td>Refresh cookie lifetime</td></tr><tr><td><code>COOKIE_SECURE</code></td><td>No</td><td>derived</td><td><code>true</code>/<code>1</code> or <code>false</code>/<code>0</code> forces <code>Secure</code> cookies on or off. Unset, it follows the scheme of <code>GITHUB_CALLBACK_URL</code>, then <code>NODE_ENV=production</code></td></tr><tr><td><code>WAFFLEBASE_DESKTOP_WINDOWS_ORIGIN</code></td><td>No</td><td>accepted</td><td><code>false</code> stops accepting sign-in from the Windows desktop app&#39;s window (<code>http://tauri.localhost</code>). Anything else keeps it. See <a href="/docs/developers/self-hosting/sign-in.html#allow-desktop-app-sign-in">Allow desktop app sign-in</a></td></tr></tbody></table><h2 id="backend-github-enterprise" tabindex="-1">Backend: GitHub Enterprise <a class="header-anchor" href="#backend-github-enterprise" aria-label="Permalink to &quot;Backend: GitHub Enterprise&quot;">​</a></h2><p>Set all four to sign in against a GitHub Enterprise Server instance. Unset, sign-in uses github.com. See <a href="/docs/developers/self-hosting/sign-in.html#use-github-enterprise">Use GitHub Enterprise</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>GITHUB_AUTHORIZATION_URL</code></td><td>No</td><td>github.com</td><td><code>https://&lt;host&gt;/login/oauth/authorize</code></td></tr><tr><td><code>GITHUB_TOKEN_URL</code></td><td>No</td><td>github.com</td><td><code>https://&lt;host&gt;/login/oauth/access_token</code></td></tr><tr><td><code>GITHUB_USER_PROFILE_URL</code></td><td>No</td><td>github.com</td><td><code>https://&lt;host&gt;/api/v3/user</code></td></tr><tr><td><code>GITHUB_USER_EMAIL_URL</code></td><td>No</td><td>github.com</td><td><code>https://&lt;host&gt;/api/v3/user/emails</code></td></tr></tbody></table><h2 id="backend-google-sign-in" tabindex="-1">Backend: Google sign-in <a class="header-anchor" href="#backend-google-sign-in" aria-label="Permalink to &quot;Backend: Google sign-in&quot;">​</a></h2><p>Set all three to show <strong>Continue with Google</strong>. With any one missing, Google sign-in is off and the backend logs which variable is missing. See <a href="/docs/developers/self-hosting/sign-in.html#set-up-google-sign-in">Set up Google sign-in</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>GOOGLE_CLIENT_ID</code></td><td>No</td><td>none</td><td>Google OAuth client ID</td></tr><tr><td><code>GOOGLE_CLIENT_SECRET</code></td><td>No</td><td>none</td><td>Google OAuth client secret</td></tr><tr><td><code>GOOGLE_CALLBACK_URL</code></td><td>No</td><td>none</td><td><code>https://&lt;backend&gt;/auth/google/callback</code>. Required, unlike GitHub&#39;s</td></tr></tbody></table><h2 id="backend-yorkie" tabindex="-1">Backend: Yorkie <a class="header-anchor" href="#backend-yorkie" aria-label="Permalink to &quot;Backend: Yorkie&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>YORKIE_RPC_ADDR</code></td><td>No</td><td><code>http://localhost:8080</code></td><td>Yorkie address the backend uses. Browsers use <code>VITE_YORKIE_RPC_ADDR</code> instead</td></tr><tr><td><code>YORKIE_PUBLIC_KEY</code></td><td>No</td><td>none</td><td>Yorkie project public key for the backend&#39;s client</td></tr><tr><td><code>YORKIE_SECRET_KEY</code></td><td>For production</td><td>none</td><td>Yorkie project secret key. Verifies the auth and event webhooks, and shows who is editing in the documents list. Without it, both webhooks are refused</td></tr><tr><td><code>YORKIE_TOKEN_EXPIRES_IN</code></td><td>No</td><td><code>10m</code></td><td>Lifetime of the token browsers present to the Yorkie auth webhook</td></tr><tr><td><code>YORKIE_AUTH_WEBHOOK_ENFORCE</code></td><td>No</td><td>unset (enforce)</td><td>Only <code>false</code> (any case) selects shadow mode, which logs decisions but allows every request. The public template gallery requires the literal <code>true</code></td></tr></tbody></table><h2 id="backend-blob-storage" tabindex="-1">Backend: blob storage <a class="header-anchor" href="#backend-blob-storage" aria-label="Permalink to &quot;Backend: blob storage&quot;">​</a></h2><p>Two buckets with independent settings. Outside production each value falls back to the local MinIO container (<code>http://localhost:9000</code>, region <code>us-east-1</code>, keys <code>minioadmin</code>). With <code>NODE_ENV=production</code> there are no fallbacks. See <a href="/docs/developers/self-hosting/deploy.html#set-up-blob-storage">Set up blob storage</a>.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>FILE_STORAGE_ENDPOINT</code></td><td>In production</td><td>MinIO</td><td>S3 endpoint for uploaded files, PDFs, and image documents</td></tr><tr><td><code>FILE_STORAGE_BUCKET</code></td><td>In production</td><td><code>wafflebase-files</code></td><td>Bucket name</td></tr><tr><td><code>FILE_STORAGE_REGION</code></td><td>In production</td><td><code>us-east-1</code></td><td>Region</td></tr><tr><td><code>FILE_STORAGE_ACCESS_KEY</code></td><td>In production</td><td><code>minioadmin</code></td><td>Access key</td></tr><tr><td><code>FILE_STORAGE_SECRET_KEY</code></td><td>In production</td><td><code>minioadmin</code></td><td>Secret key</td></tr><tr><td><code>FILE_STORAGE_PREFIX</code></td><td>No</td><td>empty</td><td>Object-key prefix inside a shared bucket. Surrounding <code>/</code> are trimmed. Do not change it after the first upload</td></tr><tr><td><code>IMAGE_STORAGE_ENDPOINT</code></td><td>In production</td><td>MinIO</td><td>S3 endpoint for images embedded in sheets, docs, slides, and boards</td></tr><tr><td><code>IMAGE_STORAGE_BUCKET</code></td><td>In production</td><td><code>wafflebase-images</code></td><td>Bucket name</td></tr><tr><td><code>IMAGE_STORAGE_REGION</code></td><td>In production</td><td><code>us-east-1</code></td><td>Region</td></tr><tr><td><code>IMAGE_STORAGE_ACCESS_KEY</code></td><td>In production</td><td><code>minioadmin</code></td><td>Access key</td></tr><tr><td><code>IMAGE_STORAGE_SECRET_KEY</code></td><td>In production</td><td><code>minioadmin</code></td><td>Secret key</td></tr><tr><td><code>IMAGE_STORAGE_PREFIX</code></td><td>No</td><td>empty</td><td>Object-key prefix, as above</td></tr></tbody></table><h2 id="backend-datasources-and-lakehouse" tabindex="-1">Backend: datasources and lakehouse <a class="header-anchor" href="#backend-datasources-and-lakehouse" aria-label="Permalink to &quot;Backend: datasources and lakehouse&quot;">​</a></h2><p>Out-of-range integers are clamped to the nearest bound and non-integers keep the default; both log a warning at startup. An invalid memory limit falls back to <code>512MB</code> without a warning.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>DATASOURCE_ENCRYPTION_KEY</code></td><td>To use datasources</td><td>none</td><td>64 hex characters (<code>openssl rand -hex 32</code>). Encrypts stored database and lakehouse credentials. Changing it makes stored credentials unreadable</td></tr><tr><td><code>LAKEHOUSE_ALLOWED_ENDPOINTS</code></td><td>No</td><td>empty</td><td>Comma-separated exact HTTP(S) origins allowed as custom S3, Azure, or GCS endpoints and Iceberg REST catalogs. Empty allows none</td></tr><tr><td><code>LAKEHOUSE_QUERY_TIMEOUT_MS</code></td><td>No</td><td><code>30000</code></td><td>Query timeout, <code>100</code>–<code>300000</code></td></tr><tr><td><code>LAKEHOUSE_DUCKDB_MEMORY_LIMIT</code></td><td>No</td><td><code>512MB</code></td><td>Integer followed by <code>KB</code>, <code>MB</code>, or <code>GB</code></td></tr><tr><td><code>LAKEHOUSE_DUCKDB_THREADS</code></td><td>No</td><td><code>2</code></td><td><code>1</code>–<code>32</code></td></tr><tr><td><code>LAKEHOUSE_DUCKDB_POOL_SIZE</code></td><td>No</td><td><code>2</code></td><td><code>1</code>–<code>8</code>. Operations still run one at a time</td></tr><tr><td><code>LAKEHOUSE_DUCKDB_MAX_PENDING</code></td><td>No</td><td><code>64</code></td><td>Queued operations, <code>1</code>–<code>1000</code></td></tr><tr><td><code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code></td><td>No</td><td><code>~/.duckdb</code>; <code>/app/.duckdb-extensions</code> in the image</td><td>Where DuckDB loads extensions from</td></tr><tr><td><code>LAKEHOUSE_ALLOW_LOCAL_PATHS</code></td><td>No</td><td><code>false</code></td><td><code>true</code> lets lakehouse tables read the server&#39;s own filesystem</td></tr><tr><td><code>LAKEHOUSE_LOCAL_ROOT</code></td><td>With local paths</td><td>none</td><td>The only directory local paths may point into</td></tr></tbody></table><h2 id="backend-webhooks" tabindex="-1">Backend: webhooks <a class="header-anchor" href="#backend-webhooks" aria-label="Permalink to &quot;Backend: webhooks&quot;">​</a></h2><p>Webhooks stay off until <code>WAFFLEBASE_WEBHOOKS_ENABLED</code> is <code>true</code>. See <a href="/docs/developers/webhooks.html">Webhooks</a> for the owner side.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_WEBHOOKS_ENABLED</code></td><td>To use webhooks</td><td>off</td><td>Only the exact value <code>true</code> turns webhooks on. Off, nothing is recorded or sent and owners see a muted <strong>Webhooks</strong> section</td></tr><tr><td><code>WAFFLEBASE_SECRETS_ENCRYPTION_KEY</code></td><td>With webhooks, unless <code>DATASOURCE_ENCRYPTION_KEY</code> is set</td><td><code>DATASOURCE_ENCRYPTION_KEY</code></td><td>64 hex characters (<code>openssl rand -hex 32</code>). Encrypts webhook signing secrets. Changing it makes existing webhooks unable to sign; delete and re-create them</td></tr><tr><td><code>WAFFLEBASE_WEBHOOK_ALLOWED_CIDRS</code></td><td>No</td><td>empty</td><td>Comma-separated exact CIDRs, such as <code>10.0.4.0/24</code>, that webhooks may reach although they are private addresses. Entries that do not parse are ignored</td></tr><tr><td><code>WAFFLEBASE_WEBHOOK_ALLOW_HTTP</code></td><td>No</td><td>off</td><td>Only the exact value <code>true</code> allows <code>http://</code> endpoints</td></tr><tr><td><code>WAFFLEBASE_WEBHOOK_QUIET_MS</code></td><td>No</td><td><code>60000</code></td><td><code>document.content_updated</code> is sent once a document has had no edits for this long</td></tr><tr><td><code>WAFFLEBASE_WEBHOOK_MAX_WAIT_MS</code></td><td>No</td><td><code>300000</code></td><td>…or at most this long after the first edit, while editing continues</td></tr></tbody></table><p><code>url</code> and <code>api_url</code> in payloads come from <code>FRONTEND_URL</code> and <code>WAFFLEBASE_API_ORIGIN</code> (falling back to the origin of <code>GITHUB_CALLBACK_URL</code>).</p><h2 id="backend-templates" tabindex="-1">Backend: templates <a class="header-anchor" href="#backend-templates" aria-label="Permalink to &quot;Backend: templates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_TEMPLATE_REVIEWER_IDS</code></td><td>For the public gallery</td><td>empty</td><td>Comma-separated user IDs allowed to approve public templates. Empty means nobody, which keeps the public gallery closed. Entries that are not positive integers are ignored</td></tr></tbody></table><h2 id="backend-share-link-analytics" tabindex="-1">Backend: share-link analytics <a class="header-anchor" href="#backend-share-link-analytics" aria-label="Permalink to &quot;Backend: share-link analytics&quot;">​</a></h2><p>Set all three to turn analytics on. The Kafka brokers turn on recording views; the StarRocks DSN turns on the dashboards and the <strong>Analytics</strong> sidebar entry. Without the DSN, the dashboard says analytics is not enabled.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_KAFKA_ADDRESSES</code></td><td>No</td><td>none</td><td>Comma-separated Kafka brokers for view events. Unset, no views are recorded</td></tr><tr><td><code>WAFFLEBASE_KAFKA_TOPIC</code></td><td>No</td><td><code>wafflebase-view-events</code></td><td>Kafka topic for view events</td></tr><tr><td><code>WAFFLEBASE_STARROCKS_DSN</code></td><td>No</td><td>none</td><td><code>user:pass@tcp(host:port)/db</code> for the analytics warehouse. Unset, the dashboards are off</td></tr></tbody></table><h2 id="backend-error-tracking" tabindex="-1">Backend: error tracking <a class="header-anchor" href="#backend-error-tracking" aria-label="Permalink to &quot;Backend: error tracking&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SENTRY_DSN</code></td><td>No</td><td>none</td><td>Your Sentry project DSN. Unset, nothing is reported</td></tr><tr><td><code>SENTRY_ENVIRONMENT</code></td><td>No</td><td><code>NODE_ENV</code></td><td><code>environment</code> tag on every event</td></tr><tr><td><code>SENTRY_RELEASE</code></td><td>No</td><td>backend package version</td><td><code>release</code> tag on every event</td></tr><tr><td><code>SENTRY_TRACES_SAMPLE_RATE</code></td><td>No</td><td><code>0.1</code></td><td>Trace sampling rate, <code>0</code>–<code>1</code>. Invalid values use <code>0.1</code></td></tr></tbody></table><h2 id="backend-demo-reset" tabindex="-1">Backend: demo reset <a class="header-anchor" href="#backend-demo-reset" aria-label="Permalink to &quot;Backend: demo reset&quot;">​</a></h2><p>Restores chosen documents to a pinned version once a day. Unset, no timer runs.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_DEMO_RESET_TARGETS</code></td><td>No</td><td>none</td><td>Comma-separated <code>&lt;shareToken&gt;:&lt;revisionId&gt;</code> pairs. An entry without <code>:&lt;revisionId&gt;</code> is not reset; its recent versions with the label below are logged at startup so you can pick an ID. Editor share tokens are write credentials, so set this from a secret</td></tr><tr><td><code>WAFFLEBASE_DEMO_RESET_LABEL</code></td><td>No</td><td><code>demo-golden</code></td><td>Version name the startup listing filters on</td></tr><tr><td><code>WAFFLEBASE_DEMO_RESET_HOUR_UTC</code></td><td>No</td><td><code>15</code></td><td>Hour of day (UTC, <code>0</code>–<code>23</code>) the reset runs. Invalid values use <code>15</code></td></tr></tbody></table><h2 id="frontend-build-time-variables" tabindex="-1">Frontend: build-time variables <a class="header-anchor" href="#frontend-build-time-variables" aria-label="Permalink to &quot;Frontend: build-time variables&quot;">​</a></h2><p>Supply these when you run <code>pnpm frontend build</code>. See <a href="/docs/developers/self-hosting/deploy.html#build-the-frontend">Build the frontend</a> for where to put them.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>VITE_BACKEND_API_URL</code></td><td>Yes</td><td><code>http://localhost:3000</code></td><td>Public origin of the backend</td></tr><tr><td><code>VITE_YORKIE_RPC_ADDR</code></td><td>Yes</td><td><code>http://localhost:8080</code></td><td>Address browsers reach Yorkie at</td></tr><tr><td><code>VITE_YORKIE_PUBLIC_KEY</code></td><td>If your Yorkie project has one</td><td>empty</td><td>Yorkie project public key. Not a secret</td></tr><tr><td><code>VITE_FRONTEND_BASENAME</code></td><td>No</td><td><code>/</code></td><td>Router base path. Serving from a subpath needs more than this variable</td></tr><tr><td><code>VITE_SERVICE_WORKER</code></td><td>No</td><td>on</td><td><code>off</code> turns off the offline app shell the <a href="/docs/start/desktop.html#use-the-app-offline">desktop app</a> uses to start without a connection, and removes one an earlier build installed</td></tr><tr><td><code>VITE_GA_ID</code></td><td>No</td><td>none</td><td>Google Analytics measurement ID. Leave unset unless the property is yours</td></tr><tr><td><code>VITE_SENTRY_DSN</code></td><td>No</td><td>none</td><td>Your Sentry project DSN for browser errors</td></tr><tr><td><code>VITE_SENTRY_ENVIRONMENT</code></td><td>No</td><td>build mode (<code>production</code>)</td><td><code>environment</code> tag</td></tr><tr><td><code>VITE_SENTRY_TRACES_SAMPLE_RATE</code></td><td>No</td><td><code>0.1</code></td><td>Trace sampling rate, <code>0</code>–<code>1</code></td></tr><tr><td><code>VITE_DEMO_SHARED_TOKEN</code></td><td>No</td><td>none</td><td>Share token for the sheet demo on the homepage</td></tr><tr><td><code>VITE_DEMO_DOC_SHARED_TOKEN</code></td><td>No</td><td>none</td><td>Share token for the docs demo</td></tr><tr><td><code>VITE_DEMO_SLIDES_SHARED_TOKEN</code></td><td>No</td><td>none</td><td>Share token for the slides demo</td></tr></tbody></table><h2 id="frontend-build-environment" tabindex="-1">Frontend: build environment <a class="header-anchor" href="#frontend-build-environment" aria-label="Permalink to &quot;Frontend: build environment&quot;">​</a></h2><p>These configure the build itself and are never compiled into the bundle.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>SENTRY_AUTH_TOKEN</code></td><td>No</td><td>none</td><td>When set, the build emits source maps, uploads them to Sentry, and deletes them from <code>dist</code></td></tr><tr><td><code>SENTRY_ORG</code></td><td>With the token</td><td><code>wafflebase</code></td><td>Sentry organization to upload to. Set your own</td></tr><tr><td><code>SENTRY_PROJECT</code></td><td>With the token</td><td><code>wafflebase</code></td><td>Sentry project to upload to. Set your own</td></tr></tbody></table><h2 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>VITE_GA_ID</code></td><td>No</td><td>none</td><td>Google Analytics for the docs pages built by <code>pnpm build:all</code>. Template: <code>packages/documentation/.env.production.example</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/deploy.html">Deploy to production</a> to apply these values.</li><li><a href="/docs/developers/self-hosting/sign-in.html">Sign-in providers</a> for the OAuth variables in context.</li><li><a href="/docs/developers/self-hosting/optional-features.html">Optional features</a> for analytics, lakehouse, error tracking, and templates.</li><li><a href="https://github.com/wafflebase/wafflebase/blob/main/packages/backend/README.md" target="_blank" rel="noreferrer"><code>packages/backend/README.md</code></a> for the per-variable rationale.</li></ul>',48)])])}const E=e(r,[["render",n]]);export{b as __pageData,E as default};
